-- Pilot 与机场对称：flyto、框选变焦（上云 method 相同，仅协议版本与指令编码不同）。
INSERT INTO dji_cloud_command (model_code, protocol_version, code, name, custom_fields)
SELECT
  'data_protocol_dji_pilot',
  'dji-pilot-1.16.1',
  replace(c.code, 'proto-dji-dock-', 'proto-dji-pilot-'),
  c.name,
  jsonb_set(c.custom_fields, '{protocol_version}', '["dji-pilot-1.16.1"]'::jsonb, true)
FROM dji_cloud_command c
WHERE c.code IN ('proto-dji-dock-fly-to-point', 'proto-dji-dock-camera-frame-zoom')
  AND NOT EXISTS (
    SELECT 1 FROM dji_cloud_command x
    WHERE x.code = replace(c.code, 'proto-dji-dock-', 'proto-dji-pilot-')
  );

INSERT INTO ent_data_protocol_t1 (
  tenant_id, entity_type_code, model_id, name, code, status, custom_fields, command_direction, creator, deleted
)
SELECT
  1, 'data_protocol', m.id, c.name, c.code, 1,
  c.custom_fields || jsonb_build_object(
    'communication_protocol', 'mqtt',
    'protocol_channel', 'services',
    'mqtt_topic', 'thing/product/{gateway_sn}/services'
  ),
  'downlink', 'seed', false
FROM dji_cloud_command c
JOIN dynamic_model m ON m.deleted = false AND m.tenant_id = 1 AND m.code = c.model_code
WHERE NOT EXISTS (
  SELECT 1 FROM ent_data_protocol_t1 e
  WHERE e.tenant_id = 1 AND e.code = c.code AND e.deleted = false
);

UPDATE ent_data_protocol_t1 e
SET
  name = c.name,
  model_id = m.id,
  command_direction = 'downlink',
  status = 1,
  deleted = false,
  custom_fields = c.custom_fields || jsonb_build_object(
    'communication_protocol', 'mqtt',
    'protocol_channel', 'services',
    'mqtt_topic', 'thing/product/{gateway_sn}/services'
  ),
  updater = 'seed',
  update_time = CURRENT_TIMESTAMP
FROM dji_cloud_command c
JOIN dynamic_model m ON m.deleted = false AND m.tenant_id = 1 AND m.code = c.model_code
WHERE e.tenant_id = 1 AND e.code = c.code;

INSERT INTO dynamic_entity_category_relation_t1 (
  tenant_id, category_id, entity_type_code, entity_id, domain, sort, creator, deleted
)
SELECT 1, cat.id, 'data_protocol', e.id, NULL, 0, 'seed', false
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
JOIN dynamic_category cat ON cat.deleted = false AND cat.tenant_id = 1 AND cat.code = 'cat-protocol-dji-uav'
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_category_relation_t1 r
  WHERE r.deleted = false AND r.tenant_id = 1 AND r.entity_type_code = 'data_protocol'
    AND r.entity_id = e.id AND r.category_id = cat.id
);

INSERT INTO dynamic_entity_field_index_t1
  (entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted)
SELECT e.id, e.model_id, v.field_code, v.value_string, v.value_number, 'seed', 1, false
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
JOIN (VALUES
  ('opcode', NULL::text, 0::bigint),
  ('exchange_mode', 'sync_wait_result', NULL::bigint)
) AS v(field_code, value_string, value_number) ON true
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = v.field_code
);

INSERT INTO dynamic_entity_field_index_t1
  (entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted)
SELECT e.id, e.model_id, 'protocol_version', c.protocol_version, NULL, 'seed', 1, false
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'protocol_version'
);

UPDATE dynamic_entity_field_index_t1 idx
SET model_id = e.model_id,
    value_string = CASE
      WHEN idx.field_code = 'protocol_version' THEN c.protocol_version
      WHEN idx.field_code = 'exchange_mode' THEN 'sync_wait_result'
      ELSE idx.value_string
    END,
    value_number = CASE WHEN idx.field_code = 'opcode' THEN 0 ELSE idx.value_number END,
    deleted = false,
    updater = 'seed',
    update_time = CURRENT_TIMESTAMP
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.tenant_id = 1 AND e.code = c.code
WHERE idx.entity_id = e.id
  AND idx.field_code IN ('opcode', 'exchange_mode', 'protocol_version');

UPDATE ent_data_protocol_t1
SET deleted = true, updater = 'seed', update_time = CURRENT_TIMESTAMP
WHERE tenant_id = 1 AND deleted = false AND code = 'proto-dji-pilot-return-home';

UPDATE ent_protocol_mapping_t1
SET deleted = true, updater = 'seed', update_time = CURRENT_TIMESTAMP
WHERE tenant_id = 1 AND deleted = false AND code = 'map-land-dji-pilot';

INSERT INTO dynamic_entity_field_index_t1
  (entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted)
SELECT e.id, e.model_id, v.field_code, v.value_string, NULL, 'seed', 1, false
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
JOIN (VALUES
  ('communication_protocol', 'mqtt'),
  ('protocol_channel', 'services'),
  ('mqtt_topic', 'thing/product/{gateway_sn}/services')
) AS v(field_code, value_string) ON true
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = v.field_code
);

UPDATE dynamic_entity_field_index_t1 idx
SET model_id = e.model_id,
    value_string = v.value_string,
    deleted = false,
    updater = 'seed',
    update_time = CURRENT_TIMESTAMP
FROM dji_cloud_command c
JOIN ent_data_protocol_t1 e ON e.tenant_id = 1 AND e.deleted = false AND e.code = c.code
JOIN (VALUES
  ('communication_protocol', 'mqtt'),
  ('protocol_channel', 'services'),
  ('mqtt_topic', 'thing/product/{gateway_sn}/services')
) AS v(field_code, value_string) ON true
WHERE idx.entity_id = e.id
  AND idx.tenant_id = 1
  AND idx.field_code = v.field_code;

COMMIT;
